source.javascript:
function longWords(text, n) {
  return text
    .split(' ')
    .filter((word) => word.length > n)
    .map((word) => word.toUpperCase())
}

source.typescript:
function longWords(text: string, n: number): string[] {
  return text
    .split(' ')
    .filter((word) => word.length > n)
    .map((word) => word.toUpperCase())
}
